'use client';

import { createContext, useContext, useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import Link from '@/lib/navigation';
import { apiFetch, assetUrl, pageUrl, adminLoginUrl, clearAdminSession } from '@/lib/client';
import frontendConfig from '@/frontend.config.json';
const publicStoreUrl=frontendConfig.publicUrl;
import { ArrowDownLeft, ArrowRight, ArrowUpRight, Check, CheckCircle2, ChefHat, ChevronDown, ChevronRight, ClipboardList, CreditCard, Download, Flame, LayoutDashboard, LoaderCircle, Package, Pencil, Plus, RefreshCw, Search, Settings, ShoppingBag, Truck, Wallet, X } from 'lucide-react';
import { categories, money, statusLabels, type AdminAction, type Ingredient, type Movement, type Order, type OrderStatus, type Product, type StoreConfig, type StoreState } from '@/lib/domain';
import './admin.css';
import IonicDialog from '@/components/ionic-dialog';
import NativeAdminLogin from './native-login';
import { isNativeApp } from '@/lib/platform';
import { exportCsv } from '@/lib/export-csv';
import CashPanel, { PaymentDialog } from './cash-panel';

type Tab = 'resumen' | 'caja' | 'pedidos' | 'inventario' | 'catalogo' | 'ajustes';
const tabs: { id: Tab; label: string; icon: typeof Package }[] = [{ id: 'resumen', label: 'Resumen', icon: LayoutDashboard }, { id: 'pedidos', label: 'Pedidos', icon: ClipboardList }, { id: 'caja', label: 'Caja y finanzas', icon: Wallet }, { id: 'inventario', label: 'Inventario', icon: Package }, { id: 'catalogo', label: 'Catálogo', icon: ShoppingBag }, { id: 'ajustes', label: 'Configuración', icon: Settings }];
const flow: OrderStatus[] = ['pendiente', 'aceptado', 'preparando', 'listo', 'entregado'];
const dayKey = (date: string | Date) => new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Argentina/Buenos_Aires', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(date));
const time = (date: string) => new Intl.DateTimeFormat('es-AR', { timeZone: 'America/Argentina/Buenos_Aires', hour: '2-digit', minute: '2-digit' }).format(new Date(date));
const dateLabel = (date: string | Date) => new Intl.DateTimeFormat('es-AR', { timeZone: 'America/Argentina/Buenos_Aires', day: 'numeric', month: 'short' }).format(new Date(date));
const quantity = (amount: number) => new Intl.NumberFormat('es-AR', { maximumFractionDigits: 2 }).format(amount);
const uid = (prefix: string) => `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`;
const sourceLabel: Record<Order['source'], string> = { web: 'Tienda online', whatsapp: 'WhatsApp', mostrador: 'Mostrador' };
const imageLibrary = [{"path": "/images/hero-bajonera.webp", "name": "La Bajonera · destacada"}, {"path": "/images/la-bajonera.webp", "name": "La Bajonera"}, {"path": "/images/cheese-burger.webp", "name": "Cheese Burger"}, {"path": "/images/clasica.webp", "name": "Clásica"}, {"path": "/images/jamon-queso.webp", "name": "JYQ"}, {"path": "/images/burger-loca.webp", "name": "Burger Loca"}, {"path": "/images/tata-burga.webp", "name": "Tata Burga"}, {"path": "/images/bomba-burger.webp", "name": "Bomba Burger"}, {"path": "/images/chesse-burger-triple.webp", "name": "Chesse Burger Triple"}, {"path": "/images/extra-bacon.webp", "name": "Extra Bacon"}, {"path": "/images/grand-tasty.webp", "name": "Grand Tasty"}, {"path": "/images/onion-crispy.webp", "name": "La Onion Crispy"}, {"path": "/images/bbq.webp", "name": "BBQ"}, {"path": "/images/cuarto-libra.webp", "name": "Cuarto de Libra"}, {"path": "/images/big-bacon.webp", "name": "Big Bacon"}, {"path": "/images/bomba-chesse-house.webp", "name": "Bomba Chesse House"}, {"path": "/images/combo-familiar.webp", "name": "Combo familiar"}, {"path": "/images/combo-infantil.webp", "name": "Combo infantil"}, {"path": "/images/promo-bomba-chesse.webp", "name": "Promo Bomba"}, {"path": "/images/current-papas.webp", "name": "Papas"}, {"path": "/images/current-bandeja-mixta.webp", "name": "Bandeja bajonera"}, {"path": "/images/current-panchos.webp", "name": "Panchos"}, {"path": "/images/current-milanesa-caballo.webp", "name": "Milanesa a caballo"}, {"path": "/images/current-napolitana.webp", "name": "Napolitana"}, {"path": "/images/current-pizza.webp", "name": "Pizza"}, {"path": "/images/current-empanadas.webp", "name": "Empanadas"}, {"path": "/images/current-combo-especial.webp", "name": "Combo especial"}, {"path": "/images/current-combo-pizzas.webp", "name": "Promos pizzas"}, {"path": "/images/current-cajita-4-personas.webp", "name": "Cajita para cuatro"}];

const AdminDialogContext = createContext({busy:false,error:'',clearError:()=>{}});
function Modal({title,subtitle,children,onClose,wide=false}:{title:string;subtitle?:string;children:ReactNode;onClose:()=>void;wide?:boolean}) {
  const status=useContext(AdminDialogContext);
  return <IonicDialog label={title} onClose={onClose} wide={wide} busy={status.busy} className={`adm-modal ${wide?'adm-modal-wide':''}`}><div className="adm-modal-head"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button type="button" className="adm-icon" aria-label="Cerrar" disabled={status.busy} onClick={onClose}><X size={20}/></button></div>{status.error&&<div className="bh3-dialog-error" role="alert"><span>{status.error}</span><button type="button" aria-label="Cerrar error" onClick={status.clearError}><X size={16}/></button></div>}{children}</IonicDialog>;
}

function Empty({ title, detail }: { title: string; detail: string }) { return <div className="adm-empty"><ShoppingBag size={32} /><h3>{title}</h3><p>{detail}</p></div>; }

export default function AdminPage() {
  const [state, setState] = useState<StoreState | null>(null);
  const [tab, setTab] = useState<Tab>('resumen');
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [unauthorized, setUnauthorized] = useState(false);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [query, setQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('todos');
  const [catalogFilter, setCatalogFilter] = useState('todos');
  const [expanded, setExpanded] = useState<string | null>(null);
  const [ingredientEditor, setIngredientEditor] = useState<Ingredient | null>(null);
  const [productEditor, setProductEditor] = useState<Product | null>(null);
  const [stockEditor, setStockEditor] = useState<Ingredient | null>(null);
  const [cancelOrder, setCancelOrder] = useState<Order | null>(null);
  const [paymentOrder, setPaymentOrder] = useState<Order | null>(null);
  const [shippingOrder, setShippingOrder] = useState<Order | null>(null);
  const [shippingAmount, setShippingAmount] = useState('');
  const [manualModal, setManualModal] = useState(false);
  const [movementIngredient, setMovementIngredient] = useState('todos');
  const loaded = state !== null;

  async function refresh() {
    setLoading(true); setError('');
    try {
      const response = await apiFetch('/api/admin', { cache: 'no-store' });
      if (response.status === 401 || response.status === 403) { setUnauthorized(true); return; }
      const data = await response.json() as StoreState & { error?: string };
      if (!response.ok) throw new Error(data.error || 'No pudimos cargar el local.');
      setState(data); setUnauthorized(false);
    } catch (e) { setError(e instanceof Error ? e.message : 'No pudimos conectarnos. Intentá otra vez.'); }
    finally { setLoading(false); }
  }
  useEffect(() => { const initial = setTimeout(() => { void refresh(); }, 0); return () => clearTimeout(initial); }, []);
  useEffect(() => {
    const onReturn = () => { if (/\/admin\/?$/.test(location.pathname)) void refresh(); };
    window.addEventListener('bh3:navigation',onReturn);
    return () => window.removeEventListener('bh3:navigation',onReturn);
  }, []);
  useEffect(() => {
    if (busy || !loaded || unauthorized) return;
    let disposed = false;
    const controller = new AbortController();
    const poll = async () => {
      if (document.visibilityState !== 'visible' || !/\/admin\/?$/.test(location.pathname)) return;
      try {
        const response = await apiFetch('/api/admin', { cache: 'no-store', signal: controller.signal });
        if (disposed) return;
        if (response.status === 401 || response.status === 403) { setUnauthorized(true); return; }
        if (response.ok) {
          const next = await response.json() as StoreState;
          if (!disposed) setState(next);
        }
      } catch { /* A background refresh can retry at the next interval. */ }
    };
    const timer = setInterval(() => { void poll(); }, 20000);
    window.addEventListener('focus', poll);
    return () => { disposed = true; controller.abort(); clearInterval(timer); window.removeEventListener('focus', poll); };
  }, [busy, loaded, unauthorized]);
  useEffect(() => { if (!notice) return; const timer = setTimeout(() => setNotice(''), 4500); return () => clearTimeout(timer); }, [notice]);
  async function act(action: AdminAction, success: string) {
    if (busy) return false;
    setBusy(true); setError('');
    try {
      const response = await apiFetch('/api/admin', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(action) });
      if (response.status === 401 || response.status === 403) { setUnauthorized(true); return false; }
      const data = await response.json() as { state: StoreState; error?: string };
      if (!response.ok) throw new Error(data.error || 'No pudimos guardar el cambio.');
      setState(data.state); setNotice(success); return true;
    } catch (e) { setError(e instanceof Error ? e.message : 'No pudimos guardar. Intentá otra vez.'); return false; }
    finally { setBusy(false); }
  }
  function changeTab(next: Tab) { setTab(next); setQuery(''); setError(''); }

  const today = dayKey(new Date());
  const orders = useMemo(() => [...(state?.orders || [])].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [state]);
  const todayOrders = orders.filter(o => dayKey(o.createdAt) === today);
  const paidToday = new Set(state?.cash?.movements.filter(m => m.kind === 'sale' && dayKey(m.occurredAt) === today).map(m => m.orderId));
  const sales = orders.filter(o => o.paid && o.status !== 'cancelado' && paidToday.has(o.id));
  const revenue = sales.reduce((sum, o) => sum + o.total, 0);
  const lowStock = (state?.ingredients || []).filter(i => i.stock <= i.minStock);
  const activeOrders = orders.filter(o => o.status !== 'entregado' && o.status !== 'cancelado');
  const matches = (value: string) => value.toLocaleLowerCase('es').includes(query.trim().toLocaleLowerCase('es'));
  const filteredOrders = orders.filter(o => (statusFilter === 'todos' || (statusFilter === 'sin-pago' ? !o.paid && o.status !== 'cancelado' : o.status === statusFilter)) && matches(`${o.number} ${o.customer.name} ${o.customer.phone}`));
  const filteredIngredients = (state?.ingredients || []).filter(i => matches(i.name));
  const filteredProducts = (state?.products || []).filter(p => (catalogFilter === 'todos' || (catalogFilter === 'archivados' ? !p.active : p.category === catalogFilter)) && matches(p.name));
  const productCounts: Record<string, { name: string; count: number }> = {};
  sales.forEach(o => o.lines.forEach(l => { productCounts[l.productId] ||= { name: l.name, count: 0 }; productCounts[l.productId].count += l.quantity; }));
  const topProducts = Object.values(productCounts).sort((a, b) => b.count - a.count).slice(0, 5);
  const movements = [...(state?.movements || [])].sort((a, b) => b.createdAt.localeCompare(a.createdAt)).filter(m => movementIngredient === 'todos' || m.ingredientId === movementIngredient);

  function exportSales() {
    const rows = [['Pedido', 'Fecha', 'Cliente', 'Origen', 'Entrega', 'Estado', 'Pago verificado', 'Total ARS'], ...orders.map(o => [`BH-${o.number}`, new Date(o.createdAt).toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' }), o.customer.name, sourceLabel[o.source], o.customer.fulfillment, statusLabels[o.status], o.paid ? 'Sí' : 'No', String(o.total)])];
    void exportCsv(`burger-house-ventas-${today}.csv`, rows);
  }

  if (unauthorized && isNativeApp()) return <NativeAdminLogin onSuccess={() => {void refresh();}} />;
  if (unauthorized) return <main className="adm-access"><div className="adm-access-card"><img src={assetUrl('/images/logo.png')} alt="Burger House 3" /><span className="adm-eyebrow">ADMINISTRACIÓN</span><h1>Tu local, bajo control.</h1><p>Ingresá con la cuenta autorizada para gestionar pedidos, catálogo e inventario.</p><a className="adm-btn adm-btn-yellow" href={adminLoginUrl()} target="_top">Ingresar al panel <ArrowRight size={18} /></a><Link className="adm-back" href={publicStoreUrl}>Volver a la tienda</Link></div></main>;
  if (!state) return <main className="adm-access"><div className="adm-access-card">{loading ? <><LoaderCircle className="adm-spin" size={36} /><h1>Abriendo el local…</h1></> : <><h1>No pudimos conectarnos.</h1><p>{error}</p><button className="adm-btn adm-btn-yellow" onClick={refresh}>Reintentar</button><Link className="adm-back" href={publicStoreUrl}>Volver a la tienda</Link></>}</div></main>;

  const renderOrder = (order: Order) => {
    const open = expanded === order.id;
    const next = flow[flow.indexOf(order.status) + 1];
    return <article className={`adm-order ${open ? 'adm-order-open' : ''}`} key={order.id}>
      <button className="adm-order-summary" onClick={() => setExpanded(open ? null : order.id)} aria-expanded={open}>
        <div className="adm-order-number"><span>#{String(order.number).padStart(3, '0')}</span><small>{dateLabel(order.createdAt)} · {time(order.createdAt)}</small></div>
        <div className="adm-order-customer"><strong>{order.customer.name}</strong><small>{order.lines.reduce((s, l) => s + l.quantity, 0)} productos · {sourceLabel[order.source]} · {order.customer.fulfillment === 'delivery' ? 'Delivery' : 'Retiro'}</small></div>
        <div className="adm-order-flags"><span className={`adm-status adm-status-${order.status}`}>{statusLabels[order.status]}</span><span className={`adm-payment ${order.paid ? 'adm-is-paid' : ''}`}>{order.paid ? 'Pago verificado' : order.deliveryFeePending ? 'Envío a cotizar' : 'Pago pendiente'}</span></div><strong className="adm-order-total">{money(order.total)}{order.deliveryFeePending&&<small> + envío</small>}</strong><ChevronDown size={18} className={open ? 'adm-rotate' : ''} />
      </button>
      {open && <div className="adm-order-detail"><div className="adm-order-columns"><div><h4>En la cocina</h4>{order.lines.map((line, index) => <div className="adm-line" key={`${line.key}-${index}`}><div><strong>{line.quantity} × {line.name}</strong><span>{line.variantName}</span>{line.removedNames.length > 0 && <small className="adm-removed">Sin {line.removedNames.join(', ')}</small>}{line.extraNames.length > 0 && <small className="adm-added">Extra: {line.extraNames.join(', ')}</small>}{line.notes && <small className="adm-line-note">Nota: {line.notes}</small>}</div><span>{money(line.unitPrice * line.quantity)}</span></div>)}<div className="adm-order-fee"><span>Envío</span><span>{order.deliveryFeePending ? 'A cotizar según el barrio' : order.deliveryFee ? money(order.deliveryFee) : 'Sin cargo'}</span></div></div><div className="adm-customer-box"><h4>Datos del pedido</h4><p><strong>{order.customer.name}</strong><a href={`tel:${order.customer.phone}`}>{order.customer.phone}</a></p><p>{order.customer.fulfillment === 'delivery' ? <><Truck size={16} /> Delivery a {order.customer.address}</> : <><ShoppingBag size={16} /> Retira en el local</>}</p>{order.customer.notes && <p className="adm-note">{order.customer.notes}</p>}<p className="adm-payment-method"><CreditCard size={16} /> {order.paymentMethod === 'efectivo' ? 'Efectivo' : order.paymentMethod === 'transferencia' ? 'Transferencia' : 'Mercado Pago'}</p><small>{order.stockReturned ? 'Stock reintegrado por cancelación.' : order.stockDeducted ? order.status === 'cancelado' ? 'Insumos registrados como merma.' : 'Stock descontado con el pago.' : 'El stock se descuenta al verificar el pago.'}</small></div></div>
        <div className="adm-order-actions">{order.customer.fulfillment==='delivery'&&!order.paid&&['pendiente','aceptado'].includes(order.status)&&<button className="adm-btn adm-btn-light" disabled={busy} onClick={()=>{setShippingOrder(order);setShippingAmount(order.deliveryFeePending?'':String(order.deliveryFee));}}><Truck size={16}/>{order.deliveryFeePending?'Cotizar envío':'Editar costo de envío'}</button>}{!order.paid && order.status !== 'cancelado' && <button className="adm-btn adm-btn-yellow" disabled={busy||order.deliveryFeePending} title={order.deliveryFeePending?'Primero cotizá el envío':undefined} onClick={() => setPaymentOrder(order)}><CheckCircle2 size={16} /> Verificar pago</button>}{next && order.status !== 'cancelado' && <button className="adm-btn adm-btn-light" disabled={busy || (next === 'preparando' && !order.paid)} title={next === 'preparando' && !order.paid ? 'Primero verificá el pago' : undefined} onClick={() => void act({ type: 'order-status', orderId: order.id, status: next }, `Pedido #${order.number}: ${statusLabels[next].toLowerCase()}.`)}>{next === 'aceptado' ? 'Aceptar pedido' : next === 'preparando' ? 'Comenzar preparación' : next === 'listo' ? 'Marcar como listo' : 'Marcar entregado'}<ArrowRight size={16} /></button>}{order.status !== 'cancelado' && order.status !== 'entregado' && <button className="adm-btn adm-btn-danger" disabled={busy} onClick={() => setCancelOrder(order)}>Cancelar pedido</button>}</div>
      </div>}
    </article>;
  };

  return <AdminDialogContext.Provider value={{busy,error,clearError:()=>setError('')}}><main className="adm-app">
    <aside className="adm-sidebar"><Link className="adm-brand" href={publicStoreUrl}><img src={assetUrl('/images/logo.png')} alt="Burger House 3" /><span>BURGER HOUSE <b>3</b><small>PANEL DEL LOCAL</small></span></Link><div className="adm-location"><span className="adm-live-dot" /> Marcos Paz</div><nav aria-label="Panel de administración">{tabs.map(t => { const Icon = t.icon; return <button key={t.id} className={tab === t.id ? 'adm-nav-active' : ''} aria-current={tab === t.id ? 'page' : undefined} aria-label={t.label} onClick={() => changeTab(t.id)}><Icon size={20} />{t.label}{t.id === 'pedidos' && activeOrders.length > 0 && <b>{activeOrders.length}</b>}</button>; })}</nav><div className="adm-sidebar-foot"><div className="adm-service-label"><Flame size={18} /> Gestión del local</div><p>Pedidos, inventario y caja del negocio.</p><a href={publicStoreUrl} target="_blank" rel="noreferrer">Ver la tienda <ArrowUpRight size={16} /></a><div className="adm-user"><span>BH</span><div><strong>Administradora</strong><small>Acceso completo</small></div></div></div></aside>
    <div className="adm-main"><header className="adm-topbar"><Link className="adm-mobile-brand" href={publicStoreUrl} aria-label="Volver a la tienda"><img src={assetUrl('/images/logo.png')} alt="" /><strong>BURGER HOUSE <b>3</b></strong></Link><span className="adm-breadcrumb">Tu negocio / <strong>{tabs.find(t => t.id === tab)?.label}</strong></span><div><button className="adm-text-btn" onClick={()=>{clearAdminSession();location.reload();}}>Cerrar sesión</button><span className={`adm-open-status ${state.config.acceptingOrders ? '' : 'adm-closed'}`}><span />{state.config.acceptingOrders ? 'Gestión habilitada' : 'Gestión pausada'}</span><button className="adm-icon" aria-label="Actualizar información" disabled={loading || busy} onClick={refresh}><RefreshCw size={18} className={loading ? 'adm-spin' : ''} /></button></div></header>
      <nav className="adm-mobile-nav" aria-label="Secciones">{tabs.map(t => { const Icon = t.icon; return <button key={t.id} className={tab === t.id ? 'adm-nav-active' : ''} aria-current={tab === t.id ? 'page' : undefined} aria-label={t.label} onClick={() => changeTab(t.id)}><Icon size={19} /><span>{t.id === 'caja' ? 'Caja' : t.label === 'Configuración' ? 'Ajustes' : t.label}</span></button>; })}</nav>
      <div className="adm-content">{error && <div className="adm-error" role="alert"><span>{error}</span><button aria-label="Cerrar aviso" onClick={() => setError('')}><X size={16} /></button></div>}
      <div className="adm-page-title"><div><span className="adm-eyebrow">{tab === 'resumen' ? 'EL PULSO DE TU LOCAL' : 'BURGER HOUSE 3'}</span><h1>{tab === 'resumen' ? 'Todo listo para un gran día.' : tab === 'pedidos' ? 'Pedidos' : tab === 'inventario' ? 'Inventario' : tab === 'caja' ? 'Tu caja, al detalle.' : tab === 'catalogo' ? 'Tu carta, a tu manera.' : 'Configuración del local'}</h1><p>{tab === 'resumen' ? `${new Intl.DateTimeFormat('es-AR', { weekday: 'long', day: 'numeric', month: 'long', timeZone: 'America/Argentina/Buenos_Aires' }).format(new Date())} · Así viene el servicio.` : tab === 'pedidos' ? 'Del primer antojo a la última entrega.' : tab === 'inventario' ? 'Cada ingrediente cuenta. Controlá entradas, consumos y mermas.' : tab === 'caja' ? 'Cobros, gastos y cada peso que entra o sale del negocio.' : tab === 'catalogo' ? 'Productos, variantes e ingredientes, sin complicaciones.' : 'Los detalles que ven tus clientes.'}</p></div>{(tab === 'resumen' || tab === 'pedidos') && <button className="adm-btn adm-btn-yellow" onClick={() => setManualModal(true)}><Plus size={18} />Nuevo pedido</button>}{tab === 'inventario' && <button className="adm-btn adm-btn-yellow" onClick={() => setIngredientEditor({ id: uid('ingrediente'), name: '', unit: 'u', stock: 0, minStock: 5, extraPrice: 0, extraPortion: 1, maxPerPatty: 3 })}><Plus size={18} />Nuevo ingrediente</button>}{tab === 'catalogo' && <button className="adm-btn adm-btn-yellow" onClick={() => setProductEditor({ id: uid('producto'), name: '', category: 'hamburguesas', description: '', image: '/images/hero-bajonera.webp', variants: [{ id: uid('variante'), name: 'Única', price: 0, patties: 1 }], recipe: [], extras: [], active: false })}><Plus size={18} />Nuevo producto</button>}</div>

      {tab === 'resumen' && <><section className="adm-kpis" aria-label="Indicadores del día"><div className="adm-kpi adm-kpi-featured"><span>Ventas verificadas de hoy<Wallet size={20} /></span><strong>{money(revenue)}</strong><small>{sales.length} {sales.length === 1 ? 'venta con pago verificado' : 'ventas con pago verificado'}</small></div><div className="adm-kpi"><span>Pedidos de hoy<ShoppingBag size={20} /></span><strong>{todayOrders.length}</strong><small>{todayOrders.filter(o => !o.paid && o.status !== 'cancelado').length} con pago pendiente</small></div><div className="adm-kpi"><span>En servicio<ChefHat size={20} /></span><strong>{activeOrders.length}</strong><small>{orders.filter(o => o.status === 'preparando').length} en preparación</small></div><div className="adm-kpi"><span>Ticket promedio<ArrowUpRight size={20} /></span><strong>{money(sales.length ? revenue / sales.length : 0)}</strong><small>De las ventas verificadas de hoy</small></div></section>
      {lowStock.length > 0 && <button className="adm-stock-alert" onClick={() => changeTab('inventario')}><Package size={22} /><span><strong>{lowStock.length} ingredientes necesitan atención</strong><small>{lowStock.slice(0, 4).map(i => i.name).join(', ')}{lowStock.length > 4 ? ' y más' : ''}.</small></span><ChevronRight size={20} /></button>}
      <div className="adm-dashboard-grid"><section className="adm-panel adm-live-orders"><div className="adm-panel-head"><div><h2>La cocina está en marcha <span className="adm-count">{activeOrders.length}</span></h2><p>Pedidos activos, del más reciente al más antiguo.</p></div><button className="adm-text-btn" onClick={() => changeTab('pedidos')}>Ver todos <ArrowRight size={15} /></button></div>{activeOrders.length ? activeOrders.slice(0, 5).map(renderOrder) : <Empty title="La próxima orden está por llegar" detail="Los nuevos pedidos de la tienda aparecerán acá." />}</section><section className="adm-panel"><div className="adm-panel-head"><div><h2>Los favoritos de hoy</h2><p>Los que más salen de la cocina.</p></div><Flame size={21} className="adm-yellow" /></div>{topProducts.length ? <div className="adm-ranking">{topProducts.map((p, i) => <div key={p.name}><span className="adm-rank">0{i + 1}</span><div><strong>{p.name}</strong><div className="adm-bar"><span style={{ width: `${(p.count / topProducts[0].count) * 100}%` }} /></div></div><b>{p.count}<small>unid.</small></b></div>)}</div> : <Empty title="Acá van tus favoritos" detail="Al verificar ventas vas a descubrir los productos más pedidos." />}<div className="adm-report-note">Las métricas incluyen pagos verificados y excluyen pedidos cancelados.</div></section></div>
      <section className="adm-panel"><div className="adm-panel-head"><div><h2>Últimos movimientos</h2><p>La trazabilidad de tus ingredientes.</p></div><button className="adm-text-btn" onClick={() => changeTab('inventario')}>Ver inventario <ArrowRight size={15} /></button></div><Movements movements={movements.slice(0, 5)} ingredients={state.ingredients} /></section></>}

      {tab === 'pedidos' && <><div className="adm-toolbar"><label className="adm-search"><Search size={18} /><input aria-label="Buscar pedidos" placeholder="Buscar por nombre, teléfono o número…" value={query} onChange={e => setQuery(e.target.value)} /></label><button className="adm-btn adm-btn-light" onClick={exportSales}><Download size={17} />Exportar ventas</button></div><div className="adm-filter-chips">{[{ id: 'todos', name: 'Todos' }, { id: 'sin-pago', name: 'Sin pago' }, ...flow.map(id => ({ id, name: statusLabels[id] })), { id: 'cancelado', name: 'Cancelados' }].map(f => <button key={f.id} className={statusFilter === f.id ? 'adm-chip-selected' : ''} onClick={() => setStatusFilter(f.id)}>{f.name}<span>{orders.filter(o => f.id === 'todos' || (f.id === 'sin-pago' ? !o.paid && o.status !== 'cancelado' : o.status === f.id)).length}</span></button>)}</div><section className="adm-panel adm-orders-list">{filteredOrders.length ? filteredOrders.map(renderOrder) : <Empty title="No hay pedidos para mostrar" detail={query ? 'Probá con otro nombre o número de pedido.' : 'Cuando ingrese un pedido, lo vas a encontrar acá.'} />}</section></>}

      {tab === 'inventario' && <><div className="adm-inventory-summary"><span><strong>{state.ingredients.length}</strong> ingredientes</span><span><i className="adm-live-dot" /><strong>{state.ingredients.filter(i => i.stock > i.minStock).length}</strong> con stock suficiente</span><span className="adm-yellow"><strong>{lowStock.length}</strong> por reponer</span></div><div className="adm-toolbar"><label className="adm-search"><Search size={18} /><input aria-label="Buscar ingredientes" placeholder="Buscar un ingrediente…" value={query} onChange={e => setQuery(e.target.value)} /></label><span className="adm-muted">Cantidades disponibles e ingredientes de cada producto</span></div><p className="adm-table-scroll-note" id="adm-inventory-scroll-hint">Deslizá la tabla hacia los lados para ver los datos y las acciones.</p><section className="adm-panel adm-table-wrap" tabIndex={0} role="region" aria-label="Inventario de ingredientes" aria-describedby="adm-inventory-scroll-hint"><table className="adm-table"><thead><tr><th>Ingrediente</th><th>Disponible</th><th>Mínimo</th><th>Extra por porción</th><th>Estado</th><th><span className="adm-sr-only">Acciones</span></th></tr></thead><tbody>{filteredIngredients.map(i => <tr key={i.id}><td><strong>{i.name}</strong><small>Porción extra: {quantity(i.extraPortion)} {i.unit}</small></td><td className="adm-stock-value">{quantity(i.stock)} <small>{i.unit}</small></td><td>{quantity(i.minStock)} {i.unit}</td><td>{money(i.extraPrice)}</td><td><span className={`adm-stock-badge ${i.stock <= 0 ? 'adm-no-stock' : i.stock <= i.minStock ? 'adm-low-stock' : ''}`}>{i.stock <= 0 ? 'Agotado' : i.stock <= i.minStock ? 'Stock bajo' : 'Disponible'}</span></td><td><div className="adm-table-actions"><button className="adm-btn adm-btn-light adm-btn-small" onClick={() => setStockEditor(i)}><Plus size={15} />Movimiento</button><button className="adm-icon" aria-label={`Editar ${i.name}`} onClick={() => setIngredientEditor({ ...i })}><Pencil size={16} /></button></div></td></tr>)}</tbody></table>{!filteredIngredients.length && <Empty title="No encontramos ese ingrediente" detail="Probá con otro nombre o creá uno nuevo." />}</section><section className="adm-panel"><div className="adm-panel-head"><div><h2>Historial de inventario</h2><p>Entradas, ventas, ajustes y mermas.</p></div><select className="adm-select" aria-label="Filtrar movimientos por ingrediente" value={movementIngredient} onChange={e => setMovementIngredient(e.target.value)}><option value="todos">Todos los ingredientes</option>{state.ingredients.map(i => <option key={i.id} value={i.id}>{i.name}</option>)}</select></div><Movements movements={movements.slice(0, 100)} ingredients={state.ingredients} />{movements.length > 100 && <p className="adm-report-note">Mostrando los 100 movimientos más recientes.</p>}</section></>}

      {tab === 'catalogo' && <><div className="adm-toolbar"><label className="adm-search"><Search size={18} /><input aria-label="Buscar productos" placeholder="Buscar un producto…" value={query} onChange={e => setQuery(e.target.value)} /></label><span className="adm-muted">{state.products.filter(p => p.active).length} productos publicados</span></div><div className="adm-filter-chips">{[{ id: 'todos', name: 'Todos' }, ...categories.map(c => ({ id: c.id, name: c.short })), { id: 'archivados', name: 'Archivados' }].map(c => <button className={catalogFilter === c.id ? 'adm-chip-selected' : ''} onClick={() => setCatalogFilter(c.id)} key={c.id}>{c.name}</button>)}</div><div className="adm-product-grid">{filteredProducts.map(p => <article className={`adm-product ${!p.active ? 'adm-product-inactive' : ''}`} key={p.id}><div className="adm-product-photo"><img src={assetUrl(p.image)} alt={p.name} /><span className={`adm-product-published ${p.active ? '' : 'adm-product-archived'}`}>{p.active ? 'Publicado' : 'Archivado'}</span></div><div className="adm-product-body"><span className="adm-eyebrow">{categories.find(c => c.id === p.category)?.name}</span><h3>{p.name}</h3><p>{p.description}</p><div className="adm-product-price"><strong>{p.unresolved ? 'Por confirmar' : `Desde ${money(Math.min(...p.variants.map(v => v.price)))}`}</strong><small>{p.variants.length} {p.variants.length === 1 ? 'variante' : 'variantes'}</small></div><button className="adm-btn adm-btn-light" onClick={() => setProductEditor(structuredClone(p))}><Pencil size={15} />Editar producto</button></div></article>)}</div>{!filteredProducts.length && <Empty title="Todavía no hay productos acá" detail="Agregá uno nuevo o probá con otra categoría." />}</>}

      {tab === 'caja' && <CashPanel state={state} busy={busy} onAction={act} error={error} />}
      {tab === 'ajustes' && <ConfigForm key={JSON.stringify(state.config)} config={state.config} busy={busy} onSave={config => act({ type: 'config', config }, 'La configuración del local se actualizó.')} />}
      <footer className="adm-footer"><span>BURGER HOUSE <b>3</b> · Hecho con amor.</span><span>Pedidos, inventario y caja</span></footer></div></div>
    {paymentOrder && state.cash && <PaymentDialog order={paymentOrder} cash={state.cash} error={error} busy={busy} onClose={() => setPaymentOrder(null)} onSave={async payments => { const saved = await act({type:'verify-payment',orderId:paymentOrder.id,payments},`Cobro del pedido #${paymentOrder.number} registrado. Stock actualizado.`); if(saved)setPaymentOrder(null); return saved; }} />}
    {notice && <div className="adm-toast" role="status"><CheckCircle2 size={20} />{notice}<button aria-label="Cerrar notificación" onClick={() => setNotice('')}><X size={16} /></button></div>}
    {manualModal && <Modal title="Un nuevo pedido, por favor." subtitle="Elegí el origen y armá el pedido con el catálogo interno de gestión." onClose={() => setManualModal(false)}><div className="adm-manual-options"><Link href={pageUrl('/admin/nuevo/?source=mostrador')}><ShoppingBag size={27} /><strong>Venta en mostrador</strong><span>Para clientes que compran en el local.</span><ArrowRight size={20} /></Link><Link href={pageUrl('/admin/nuevo/?source=whatsapp')}><ClipboardList size={27} /><strong>Pedido de WhatsApp</strong><span>Cargá una orden recibida por mensaje.</span><ArrowRight size={20} /></Link></div><p className="adm-form-note">La venta quedará registrada con su origen. El pago se verifica desde este panel.</p></Modal>}
    {shippingOrder&&<Modal title={`Cotizar envío · pedido #${shippingOrder.number}`} subtitle={shippingOrder.customer.address} onClose={()=>setShippingOrder(null)}><form className="adm-form" onSubmit={async e=>{e.preventDefault();if(await act({type:'delivery-fee',orderId:shippingOrder.id,amount:Number(shippingAmount)},'Costo de envío confirmado. Ya podés verificar el pago.'))setShippingOrder(null);}}><p className="adm-form-note">Confirmá el costo según el barrio. El total del pedido se actualizará antes de verificar el pago; el stock sigue intacto.</p><label>Costo del envío ($)<input autoFocus required type="number" min="0" max="100000" step="1" value={shippingAmount} onChange={e=>setShippingAmount(e.target.value)}/></label><p>Total con envío: <strong>{money(shippingOrder.subtotal+Number(shippingAmount||0))}</strong></p><div className="adm-form-footer"><button type="button" className="adm-btn adm-btn-light" onClick={()=>setShippingOrder(null)}>Cancelar</button><button className="adm-btn adm-btn-yellow" disabled={busy||shippingAmount===''}><Check size={16}/>Confirmar costo</button></div></form></Modal>}
    {cancelOrder && <Modal title={`Cancelar pedido #${cancelOrder.number}`} onClose={() => setCancelOrder(null)}><div className="adm-cancel-content"><p>{cancelOrder.stockDeducted && ['preparando', 'listo'].includes(cancelOrder.status) ? 'Este pedido ya llegó a la cocina. Los ingredientes consumidos se conservarán como merma y no volverán al stock.' : cancelOrder.stockDeducted ? 'El pedido todavía no comenzó a prepararse. Sus ingredientes se devolverán al stock automáticamente.' : 'El pedido no tiene stock descontado. Se cancelará sin modificar el inventario.'}</p><p>El cobro permanece en el libro de caja. Si corresponde devolver dinero, registrá la devolución desde Caja y finanzas para conservar su comprobante e historial.</p><div className="adm-form-footer"><button className="adm-btn adm-btn-light" onClick={() => setCancelOrder(null)}>Conservar pedido</button><button className="adm-btn adm-btn-red" disabled={busy} onClick={async () => { if (await act({ type: 'order-status', orderId: cancelOrder.id, status: 'cancelado' }, 'Pedido cancelado. Inventario actualizado según su preparación.')) setCancelOrder(null); }}>Confirmar cancelación</button></div></div></Modal>}
    {ingredientEditor && <IngredientForm ingredient={ingredientEditor} busy={busy} onClose={() => setIngredientEditor(null)} onSave={async ingredient => { if (await act({ type: 'ingredient', ingredient }, 'Ingrediente guardado.')) setIngredientEditor(null); }} />}
    {stockEditor && <StockForm ingredient={stockEditor} busy={busy} onClose={() => setStockEditor(null)} onSave={async (amount, reason, expectedStock) => { if (await act({ type: 'stock', ingredientId: stockEditor.id, amount, reason, expectedStock }, 'Movimiento registrado. Stock actualizado.')) setStockEditor(null); }} />}
    {productEditor && <ProductForm product={productEditor} ingredients={state.ingredients} busy={busy} onClose={() => setProductEditor(null)} onSave={async product => { if (await act({ type: 'product', product }, 'Producto guardado. La tienda ya está actualizada.')) setProductEditor(null); }} />}
    {error && (ingredientEditor || stockEditor || productEditor || cancelOrder || shippingOrder || paymentOrder) && <div className="adm-modal-error" role="alert">{error}<button aria-label="Cerrar error" onClick={() => setError('')}><X size={16} /></button></div>}
  </main></AdminDialogContext.Provider>;
}

function Movements({ movements, ingredients }: { movements: Movement[]; ingredients: Ingredient[] }) {
  if (!movements.length) return <Empty title="Un inventario con historia" detail="Cada entrada, ajuste o venta deja su registro acá." />;
  return <div className="adm-movements">{movements.map(m => { const ingredient = ingredients.find(i => i.id === m.ingredientId); return <div className="adm-movement" key={m.id}><span className={`adm-movement-icon ${m.amount > 0 ? 'adm-movement-positive' : ''}`}>{m.amount > 0 ? <ArrowDownLeft size={18} /> : <ArrowUpRight size={18} />}</span><div><strong>{ingredient?.name || 'Ingrediente'}</strong><small>{m.reason}</small></div><span className="adm-movement-date">{dateLabel(m.createdAt)} · {time(m.createdAt)}</span><b className={m.amount > 0 ? 'adm-green' : ''}>{m.amount > 0 ? '+' : ''}{quantity(m.amount)} <small>{ingredient?.unit || ''}</small></b></div>; })}</div>;
}

function IngredientForm({ ingredient, busy, onClose, onSave }: { ingredient: Ingredient; busy: boolean; onClose: () => void; onSave: (ingredient: Ingredient) => Promise<void> }) {
  const [value, setValue] = useState(ingredient);
  return <Modal title={ingredient.name ? `Editar ${ingredient.name}` : 'Nuevo ingrediente'} subtitle="Definí cómo se mide, cuándo reponerlo y cuánto cuesta agregarlo." onClose={onClose}><form className="adm-form" onSubmit={e => { e.preventDefault(); void onSave(value); }}><label>Nombre<input required maxLength={80} value={value.name} onChange={e => setValue({ ...value, name: e.target.value })} placeholder="Ej. Cheddar" /></label><div className="adm-form-grid"><label>Unidad<select disabled={!!ingredient.name} value={value.unit} onChange={e => setValue({ ...value, unit: e.target.value as 'g' | 'u' })}><option value="u">Unidades</option><option value="g">Gramos</option></select></label><label>Alerta de stock mínimo<input required type="number" min="0" step="0.01" value={value.minStock} onChange={e => setValue({ ...value, minStock: +e.target.value })} /></label></div><h3>Como ingrediente adicional</h3><div className="adm-form-grid"><label>Precio por porción ($)<input required type="number" min="0" value={value.extraPrice} onChange={e => setValue({ ...value, extraPrice: +e.target.value })} /></label><label>Cantidad por porción ({value.unit})<input required type="number" min="0.01" step="0.01" value={value.extraPortion} onChange={e => setValue({ ...value, extraPortion: +e.target.value })} /></label></div><label>Máximo por medallón o por producto<input required type="number" min="0" max="20" value={value.maxPerPatty} onChange={e => setValue({ ...value, maxPerPatty: +e.target.value })} /><small>Ejemplo: 3 permite hasta 3 porciones por medallón, contando las incluidas en la receta. En otros productos el límite se aplica por unidad.</small></label><p className="adm-form-note">Stock actual: {quantity(value.stock)} {value.unit}. Registrá entradas, ajustes o mermas con el botón Movimiento para conservar el historial.</p><div className="adm-form-footer"><button type="button" className="adm-btn adm-btn-light" onClick={onClose}>Cancelar</button><button className="adm-btn adm-btn-yellow" disabled={busy}><Check size={16} />Guardar ingrediente</button></div></form></Modal>;
}

function StockForm({ ingredient, busy, onClose, onSave }: { ingredient: Ingredient; busy: boolean; onClose: () => void; onSave: (amount: number, reason: string, expectedStock?: number) => Promise<void> }) {
  const [type, setType] = useState('entrada'); const [amount, setAmount] = useState(''); const [reason, setReason] = useState('');
  const delta = type === 'ajuste' ? Number(amount) - ingredient.stock : Number(amount) * (type === 'merma' ? -1 : 1);
  const nextStock = ingredient.stock + delta;
  return <Modal title={`Mover stock: ${ingredient.name}`} subtitle={`Disponible: ${quantity(ingredient.stock)} ${ingredient.unit}`} onClose={onClose}><form className="adm-form" onSubmit={e => { e.preventDefault(); void onSave(delta, `${type === 'entrada' ? 'Entrada' : type === 'ajuste' ? 'Ajuste de inventario' : 'Merma'}: ${reason}`, type === 'ajuste' ? ingredient.stock : undefined); }}><div className="adm-segmented">{[{ id: 'entrada', name: 'Entrada' }, { id: 'ajuste', name: 'Ajuste' }, { id: 'merma', name: 'Merma' }].map(t => <button type="button" key={t.id} className={type === t.id ? 'adm-selected' : ''} onClick={() => setType(t.id)}>{t.name}</button>)}</div><label>{type === 'ajuste' ? 'Cantidad real contada' : type === 'merma' ? 'Cantidad a descartar' : 'Cantidad recibida'} ({ingredient.unit})<input required type="number" min={type === 'ajuste' ? 0 : 0.01} step="0.01" max={type === 'merma' ? ingredient.stock : undefined} value={amount} onChange={e => setAmount(e.target.value)} autoFocus /></label><label>Motivo<textarea required maxLength={170} value={reason} onChange={e => setReason(e.target.value)} placeholder={type === 'entrada' ? 'Ej. Compra a proveedor' : type === 'merma' ? 'Ej. Producto vencido' : 'Ej. Conteo al cierre'} /></label><div className="adm-stock-preview"><span>Stock después del movimiento</span><strong>{quantity(nextStock)} {ingredient.unit}</strong></div><div className="adm-form-footer"><button type="button" className="adm-btn adm-btn-light" onClick={onClose}>Cancelar</button><button className="adm-btn adm-btn-yellow" disabled={busy || !amount || delta === 0 || nextStock < 0}>Registrar movimiento</button></div></form></Modal>;
}

function ProductForm({ product, ingredients, busy, onClose, onSave }: { product: Product; ingredients: Ingredient[]; busy: boolean; onClose: () => void; onSave: (product: Product) => Promise<void> }) {
  const [value, setValue] = useState(product); const [selectedIngredient, setSelectedIngredient] = useState('');
  const updateRecipe = (index: number, patch: Partial<Product['recipe'][number]>) => setValue({ ...value, recipe: value.recipe.map((r, i) => i === index ? { ...r, ...patch } : r) });
  const updateVariantRecipe = (id: string, recipe: Product['recipe'] | undefined) => setValue({ ...value, variants: value.variants.map(v => v.id === id ? { ...v, recipe } : v) });
  const submit = (event: FormEvent) => { event.preventDefault(); void onSave(value); };
  return <Modal title={product.name ? `Editar ${product.name}` : 'Nuevo producto'} subtitle="Todo lo que necesita tu cliente para elegir su próximo antojo." onClose={onClose} wide><form className="adm-form" onSubmit={submit}><div className="adm-form-grid"><label>Nombre<input required maxLength={100} value={value.name} onChange={e => setValue({ ...value, name: e.target.value })} /></label><label>Categoría<select value={value.category} onChange={e => setValue({ ...value, category: e.target.value as Product['category'] })}>{categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label></div><label>Descripción<textarea required maxLength={1000} value={value.description} onChange={e => setValue({ ...value, description: e.target.value })} /></label><div className="adm-form-grid"><label>Foto del producto<select value={value.image} onChange={e => setValue({ ...value, image: e.target.value })}>{!imageLibrary.some(i => i.path === value.image) && <option value={value.image}>Imagen actual</option>}{imageLibrary.map(i => <option key={i.path} value={i.path}>{i.name}</option>)}</select><small>Elegí una foto de la biblioteca del comercio.</small></label><label>Etiqueta opcional<input maxLength={60} value={value.badge || ''} onChange={e => setValue({ ...value, badge: e.target.value })} placeholder="Ej. La favorita" /></label></div><div className="adm-check-row"><label><input type="checkbox" checked={value.active} onChange={e => setValue({ ...value, active: e.target.checked })} />Publicado en la tienda</label><label><input type="checkbox" checked={!!value.featured} onChange={e => setValue({ ...value, featured: e.target.checked })} />Destacado</label></div>
      <div className="adm-form-section"><div className="adm-form-section-title"><h3>Variantes y precios</h3><button type="button" className="adm-text-btn" disabled={value.variants.length >= 20} onClick={() => setValue({ ...value, variants: [...value.variants, { id: uid('variante'), name: '', price: 0, patties: 1 }] })}><Plus size={15} />Agregar variante</button></div><p className="adm-form-note">Medallones define las porciones de ingredientes que escalan, y el límite de adicionales. Multiplicador permite representar packs.</p><div className="adm-variant-labels"><span>Variante</span><span>Precio ($)</span><span>Medallones</span><span>Multiplicador</span><span /></div>{value.variants.map((v, index) => <div className="adm-variant-row" key={v.id}><label><span>Variante</span><input required aria-label={`Nombre variante ${index + 1}`} maxLength={80} value={v.name} onChange={e => setValue({ ...value, variants: value.variants.map((item, i) => i === index ? { ...item, name: e.target.value } : item) })} /></label><label><span>Precio ($)</span><input required type="number" min="0" aria-label={`Precio ${v.name}`} value={v.price} onChange={e => setValue({ ...value, variants: value.variants.map((item, i) => i === index ? { ...item, price: +e.target.value } : item) })} /></label><label><span>Medallones</span><input required type="number" min="0" max="12" aria-label={`Medallones ${v.name}`} value={v.patties} onChange={e => setValue({ ...value, variants: value.variants.map((item, i) => i === index ? { ...item, patties: +e.target.value } : item) })} /></label><label><span>Multiplicador</span><input required type="number" min="0.01" step="0.01" aria-label={`Multiplicador ${v.name}`} value={v.recipeMultiplier || 1} onChange={e => setValue({ ...value, variants: value.variants.map((item, i) => i === index ? { ...item, recipeMultiplier: +e.target.value } : item) })} /></label><button type="button" className="adm-icon" aria-label={`Quitar variante ${v.name}`} disabled={value.variants.length <= 1} onClick={() => setValue({ ...value, variants: value.variants.filter((_, i) => i !== index) })}><X size={16} /></button></div>)}<label className="adm-check"><input type="checkbox" checked={!!value.unresolved} onChange={e => setValue({ ...value, unresolved: e.target.checked ? 'Precio y composición por confirmar.' : undefined })} />Precio o composición por confirmar</label>{value.unresolved && <label>Información pendiente<input required value={value.unresolved} onChange={e => setValue({ ...value, unresolved: e.target.value })} /><small>El producto no podrá comprarse hasta definirlo.</small></label>}</div>
      <div className="adm-form-section"><h3>Receta base</h3>{!value.recipe.length && <p className="adm-recipe-warning">Definí la receta base, recetas propias en todas las variantes o marcá el producto para consultar.</p>}<p className="adm-form-note">Cantidades para una unidad simple. Al verificar el pago se descuentan estas cantidades, respetando los ingredientes quitados y los extras.</p>{value.recipe.map((r, index) => { const ingredient = ingredients.find(i => i.id === r.ingredientId); return <div className="adm-recipe-row" key={r.ingredientId}><strong>{ingredient?.name || r.ingredientId}</strong><label>Cantidad ({ingredient?.unit})<input required type="number" min="0.01" step="0.01" value={r.amount} onChange={e => updateRecipe(index, { amount: +e.target.value })} /></label><label className="adm-check"><input type="checkbox" checked={!!r.scalesWithPatties} onChange={e => updateRecipe(index, { scalesWithPatties: e.target.checked })} />Por medallón</label><label className="adm-check"><input type="checkbox" checked={!!r.removable} onChange={e => updateRecipe(index, { removable: e.target.checked })} />Se puede quitar</label><button type="button" className="adm-icon" aria-label={`Quitar ${ingredient?.name} de la receta`} onClick={() => setValue({ ...value, recipe: value.recipe.filter((_, i) => i !== index) })}><X size={16} /></button></div>; })}<div className="adm-add-recipe"><select aria-label="Ingrediente para agregar a la receta" value={selectedIngredient} onChange={e => setSelectedIngredient(e.target.value)}><option value="">Elegí un ingrediente…</option>{ingredients.filter(i => !value.recipe.some(r => r.ingredientId === i.id)).map(i => <option key={i.id} value={i.id}>{i.name}</option>)}</select><button type="button" className="adm-btn adm-btn-light" disabled={!selectedIngredient} onClick={() => { setValue({ ...value, recipe: [...value.recipe, { ingredientId: selectedIngredient, amount: 1, removable: true, scalesWithPatties: false }] }); setSelectedIngredient(''); }}><Plus size={16} />Agregar</button></div></div>
      <div className="adm-form-section"><h3>Recetas por variante</h3><p className="adm-form-note">Útil para cambiar los ingredientes entre una porción simple y completa, o entre carne y pollo. Si no activás una receta propia, se usa la receta base.</p>{value.variants.map(v => <details className="adm-variant-recipe" key={v.id}><summary><span>{v.name || 'Variante sin nombre'}</span><small>{v.recipe ? `${v.recipe.length} ingredientes propios` : 'Usa la receta base'}</small><ChevronDown size={15} /></summary><label className="adm-check"><input type="checkbox" checked={v.recipe !== undefined} onChange={e => updateVariantRecipe(v.id, e.target.checked ? structuredClone(value.recipe) : undefined)} />Usar una receta propia para esta variante</label>{v.recipe !== undefined && <VariantRecipeEditor recipe={v.recipe} ingredients={ingredients} onChange={recipe => updateVariantRecipe(v.id, recipe)} />}</details>)}</div>      <div className="adm-form-section"><h3>Adicionales permitidos</h3><p className="adm-form-note">Los precios y límites se configuran en cada ingrediente del inventario.</p><div className="adm-extra-grid">{ingredients.map(i => <label className={`adm-extra-choice ${value.extras.includes(i.id) ? 'adm-extra-selected' : ''}`} key={i.id}><input type="checkbox" checked={value.extras.includes(i.id)} onChange={e => setValue({ ...value, extras: e.target.checked ? [...value.extras, i.id] : value.extras.filter(id => id !== i.id) })} /><span>{i.name}<small>+{money(i.extraPrice)}</small></span></label>)}</div></div><div className="adm-form-footer"><p className="adm-form-note">Desmarcá “Publicado” para archivar sin perder el historial de ventas.</p><button type="button" className="adm-btn adm-btn-light" onClick={onClose}>Cancelar</button><button className="adm-btn adm-btn-yellow" disabled={busy || (!value.unresolved && ((!value.recipe.length && value.variants.some(v=>!v.recipe?.length)) || value.variants.some(v=>v.recipe!==undefined&&!v.recipe.length)))}><Check size={16} />Guardar producto</button></div></form></Modal>;
}

function VariantRecipeEditor({ recipe, ingredients, onChange }: { recipe: Product['recipe']; ingredients: Ingredient[]; onChange: (recipe: Product['recipe']) => void }) {
  const [selected, setSelected] = useState('');
  const update = (index: number, patch: Partial<Product['recipe'][number]>) => onChange(recipe.map((part, i) => i === index ? { ...part, ...patch } : part));
  return <div className="adm-variant-recipe-body">{!recipe.length && <p className="adm-recipe-warning">Esta variante necesita al menos un ingrediente para guardar el producto.</p>}{recipe.map((part, index) => { const ingredient = ingredients.find(i => i.id === part.ingredientId); return <div className="adm-recipe-row" key={part.ingredientId}><strong>{ingredient?.name || part.ingredientId}</strong><label>Cantidad ({ingredient?.unit})<input required type="number" min="0.01" step="0.01" value={part.amount} onChange={e => update(index, { amount: +e.target.value })} /></label><label className="adm-check"><input type="checkbox" checked={!!part.scalesWithPatties} onChange={e => update(index, { scalesWithPatties: e.target.checked })} />Por medallón</label><label className="adm-check"><input type="checkbox" checked={!!part.removable} onChange={e => update(index, { removable: e.target.checked })} />Se puede quitar</label><button type="button" className="adm-icon" aria-label={`Quitar ${ingredient?.name} de la variante`} onClick={() => onChange(recipe.filter((_, i) => i !== index))}><X size={16} /></button></div>; })}<div className="adm-add-recipe"><select aria-label="Ingrediente para esta variante" value={selected} onChange={e => setSelected(e.target.value)}><option value="">Elegí un ingrediente…</option>{ingredients.filter(i => !recipe.some(r => r.ingredientId === i.id)).map(i => <option key={i.id} value={i.id}>{i.name}</option>)}</select><button type="button" className="adm-btn adm-btn-light" disabled={!selected} onClick={() => { onChange([...recipe, { ingredientId: selected, amount: 1, removable: true }]); setSelected(''); }}><Plus size={16} />Agregar</button></div></div>;
}

function ConfigForm({ config, busy, onSave }: { config: StoreConfig; busy: boolean; onSave: (config: StoreConfig) => Promise<boolean> }) {
  const [value, setValue] = useState(config);
  return <form className="adm-config" onSubmit={e => { e.preventDefault(); void onSave(value); }}><section className="adm-panel adm-config-panel"><h2>Información del comercio</h2><p>La identidad y los canales de contacto de tu tienda.</p><div className="adm-form"><div className="adm-form-grid"><label>Nombre del comercio<input required maxLength={80} value={value.name} onChange={e => setValue({ ...value, name: e.target.value })} /></label><label>Frase de la marca<input required maxLength={150} value={value.tagline} onChange={e => setValue({ ...value, tagline: e.target.value })} /></label></div><div className="adm-form-grid"><label>WhatsApp<input required value={value.whatsapp} onChange={e => setValue({ ...value, whatsapp: e.target.value })} placeholder="5491123344218" /><small>Número con código de país, sin espacios ni símbolos.</small></label><label>Instagram<input required value={value.instagram} onChange={e => setValue({ ...value, instagram: e.target.value })} placeholder="burgerhousee3" /></label></div></div></section><section className="adm-panel adm-config-panel"><h2>Delivery y atención</h2><p>Condiciones que se muestran antes de confirmar un pedido.</p><div className="adm-form"><div className="adm-form-grid"><label>Tarifa de delivery<select value={value.deliveryFeeMode||'fixed'} onChange={e=>setValue({...value,deliveryFeeMode:e.target.value as 'fixed'|'quote'})}><option value="quote">Cotizar según el barrio</option><option value="fixed">Tarifa fija</option></select></label>{value.deliveryFeeMode!=='quote'&&<label>Costo del envío ($)<input required type="number" min="0" max="100000" value={value.deliveryFee} onChange={e => setValue({ ...value, deliveryFee: +e.target.value })} /></label>}<label>Zona de reparto<input required maxLength={150} value={value.deliveryZone} onChange={e => setValue({ ...value, deliveryZone: e.target.value })} /></label></div><label className="adm-store-toggle"><span><strong>Recibir nuevos pedidos</strong><small>Podés pausar la tienda cuando termine el servicio.</small></span><input type="checkbox" checked={value.acceptingOrders} onChange={e => setValue({ ...value, acceptingOrders: e.target.checked })} /><span className="adm-toggle-track" /></label></div></section><div className="adm-config-footer"><p>Los cambios se aplican a los pedidos nuevos.</p><button className="adm-btn adm-btn-yellow" disabled={busy}><Check size={17} />Guardar configuración</button></div></form>;
}






